const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');

if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'dispatch') throw new Error('unsupported_resource');
const allowed = new Set(["emergency_event_id","task_title","task_description","priority"]);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const eventId = text(fields.emergency_event_id);
if (!eventId || eventId.length > 128) throw new Error('emergency_event_id_required_max_128');
const taskTitle = text(fields.task_title);
if (!taskTitle || taskTitle.length > 200) throw new Error('task_title_required_max_200');
const description = text(fields.task_description);
if (description.length > 4000) throw new Error('task_description_max_4000');
const priority = text(fields.priority) || 'medium';
if (!['low', 'medium', 'high', 'critical'].includes(priority)) throw new Error('priority_invalid');
const binding = { product, resource, dataset: 'sos-dispatch-orders', recordType: 'DispatchOrder', operation: 'emergency.dispatch.create' };
const record = { type: 'DispatchOrder', emergency_event_id: eventId, task_title: taskTitle, task_description: description, priority, status: 'pending', created_at: $now, updated_at: $now };

const audit = {
  product,
  resource,
  operation: 'emergency.dispatch.create',
  pluginId: text(envelope.pluginId),
  widgetId: text(envelope.widgetId),
  submittedBy,
  submittedAt: text(envelope.submittedAt) || $now,
};

return {
  body: { data: record, publish: false },
  audit,
  binding,
};
